<script lang="ts">
  import { onMount } from "svelte";
  import { createQuery, createInfiniteQuery } from "@tanstack/svelte-query";
  import { reactiveOptions } from "$lib/components/projects/reactive-options.svelte";
  import { page } from "$app/stores";
  import { base } from "$app/paths";
  import { authStore } from "$lib/stores/auth";
  import { workflowRunKeys, workflowKeys, workflowsApi, type WorkflowDefinition } from "$lib/api/workflows";
  import { PageShell, Section, StateBlock, Timestamp } from "$lib/components/page";
  import { Button } from "$lib/components/ui/button";
  import WorkflowAvailability from "$lib/components/workflows/WorkflowAvailability.svelte";
  import WorkflowStatus from "$lib/components/workflows/WorkflowStatus.svelte";
  import WorkflowMarkdown from "$lib/components/workflows/WorkflowMarkdown.svelte";
  import WorkflowValue from "$lib/components/workflows/WorkflowValue.svelte";
  import WorkflowFacts from "$lib/components/workflows/WorkflowFacts.svelte";
  import WorkflowTaskDetail from "$lib/components/workflows/WorkflowTaskDetail.svelte";
  import WorkflowRunControls from "$lib/components/workflows/WorkflowRunControls.svelte";
  import WorkflowPreparation from "$lib/components/workflows/WorkflowPreparation.svelte";
  import WorkflowRunForm from "$lib/components/workflows/WorkflowRunForm.svelte";
  import WorkflowVersionDiff from "$lib/components/workflows/WorkflowVersionDiff.svelte";
  import { displayValue, safeWorkflowUrl, statusLabel } from "$lib/components/workflows/helpers";
  import { reportText } from "$lib/components/workflows/report-text";
  const canRead = $derived($authStore.can("workflows.read")), canRun = $derived($authStore.can("workflows.run")), canChat = $derived($authStore.can("agent_messaging.reveal_content"));
  const id = $derived($page.params.id ?? "");
  const report = createQuery(reactiveOptions(() => ({ queryKey: workflowRunKeys.report(id), queryFn: () => workflowsApi.report(id), enabled: canRead })));
  const events = createInfiniteQuery(reactiveOptions(() => ({ queryKey: workflowRunKeys.events(id), queryFn: ({ pageParam }: { pageParam: string | undefined }) => workflowsApi.events(id,pageParam), initialPageParam: undefined as string | undefined, getNextPageParam: (last: { next_cursor: string | number | null }) => last.next_cursor == null ? undefined : String(last.next_cursor), enabled: canRead })));
  const run = $derived(canRead ? $report.data : undefined);
  const taskPages = createInfiniteQuery(reactiveOptions(() => ({ queryKey: workflowRunKeys.tasks(id), queryFn: ({ pageParam }: { pageParam: string | undefined }) => workflowsApi.runGet(id,pageParam), initialPageParam: undefined as string | undefined, getNextPageParam: (last: { next_cursor?: string | number | null }) => last.next_cursor == null ? undefined : String(last.next_cursor), enabled: canRead && !!run })));
  let now = $state(Date.now());
  onMount(() => { const timer = setInterval(() => now = Date.now(), 1000); return () => clearInterval(timer); });
  const estimatedServerNow = $derived(run?.server_time ? Date.parse(run.server_time) + (now - $report.dataUpdatedAt) : null);
  const taskRows = $derived(($taskPages.data?.pages.flatMap(p => p.tasks) ?? run?.tasks ?? []).map(task => task.status === "running" && task.claim && estimatedServerNow !== null && Date.parse(task.claim.lease_until) <= estimatedServerNow ? { ...task, status: "uncertain" } : task));
  const appliedVersion = createQuery(reactiveOptions(() => ({ queryKey: workflowKeys.definition(run?.workflow_id ?? "", run?.evaluation?.applied_version), queryFn: () => workflowsApi.get(run!.workflow_id,run!.evaluation!.applied_version), enabled: canRead && !!run?.evaluation?.applied_version })));
  const evaluation = $derived(run?.evaluation?.draft ?? run?.evaluation);
  const facts = $derived(run?.results ?? (run?.report?.results as Record<string, unknown> | undefined) ?? {});
  const issues = $derived([...(run?.open_items ?? []), ...(taskRows.filter(t => ["uncertain","blocked","failed"].includes(t.status)).map(t => `${t.title}: ${statusLabel(t.status)}.`) ?? [])]);
  const preparationDefinition = $derived(run?.document ? { document: run.document, workflow_id: run.workflow_id, version: run.workflow_version } as WorkflowDefinition : null);
  let showDiff = $state(false);
  let openTasks = $state<string[]>([]), copied = $state(""), copyError = $state("");
  async function copy(text: string, label: string) { try { await navigator.clipboard.writeText(text); copied = label; copyError = ""; } catch { copyError = "Could not copy. Select and copy the text directly."; } }
  const assignment = $derived(run ? `Continue workflow run ${run.run_id}. Read the workflows Skill and this run, acquire coordination if eligible, clarify questions and obtain explicit confirmation of the current summary before starting, claim tasks before work, record evidence, then finish and evaluate. Report: ${run.report_url}` : "");
  function actorName(actor: unknown) { if (actor && typeof actor === "object") { const a = actor as Record<string, unknown>; return String(a.name ?? a.address_id ?? (a.kind === "admin" ? "Operator" : "Agent")); } return "Recorded actor"; }
  function memberName(address: string) { const member = run?.members.find(m => m.address_id === address); return member?.name ?? member?.display_name ?? member?.agent_address ?? `agent:${address}`; }
  const duration = $derived.by(() => { if (!run?.started_at) return "Not started"; const end = run.completed_at ?? run.finished_at ?? run.updated_at; const seconds = Math.max(0, Math.floor((Date.parse(end) - Date.parse(run.started_at)) / 1000)); return `${Math.floor(seconds / 60)} min ${seconds % 60} sec${run.status === "completed" ? "" : " at last update"}`; });
</script>
<PageShell title={run?.title ?? "Run report"} description={run?.status === "completed" ? "Final report · execution and evaluation preserved together." : "Live report · results and evidence update as the work proceeds."}>
  {#snippet actions()}<Button href={`${base}/workflows/runs`} variant="outline">All runs</Button>{#if run}<Button variant="outline" onclick={() => copy(run.report_url, "Report link")}>Copy link</Button><Button variant="outline" onclick={() => copy(reportText(run, issues), "Report")}>Copy report</Button>{/if}{/snippet}
  {#if !canRead}<StateBlock state="empty" message="Workflow access required" description="Ask an owner for workflows.read to inspect this report." />{:else if $report.isPending}<StateBlock state="loading" />{:else if $report.isError}<StateBlock state="error" message={run ? "Refresh failed. Showing the previously loaded report; its data may be stale." : `Could not load run report. ${$report.error.message}`} onRetry={() => $report.refetch()} />{/if}
  {#if run}

    <WorkflowAvailability />
    <div class="flex flex-wrap items-center gap-2" aria-label="Run state"><WorkflowStatus value={run.status} />{#if run.outcome}<WorkflowStatus value={run.outcome} />{:else}<span class="text-body-sm text-muted-foreground">Outcome not yet recorded</span>{/if}<span class="text-body-sm text-muted-foreground">Updated <Timestamp value={run.updated_at} /></span>{#if $report.isFetching}<span role="status" class="text-body-sm text-muted-foreground">Refreshing…</span>{/if}</div>
    <nav aria-label="Report sections" class="flex flex-wrap gap-x-4 gap-y-2 text-body-sm"><a class="underline" href="#result">Result</a>{#if issues.length || run.status !== "completed"}<a class="underline" href="#open-work">Open work</a>{/if}{#if run.criteria?.length}<a class="underline" href="#acceptance">Acceptance checks</a>{/if}{#if Object.keys(facts).length}<a class="underline" href="#handover">Handover</a>{/if}<a class="underline" href="#tasks">Tasks</a><a class="underline" href="#evaluation">Evaluation</a><a class="underline" href="#history">History</a></nav>
    <details open={run.status !== "completed"}><summary class="cursor-pointer py-2 text-body-sm font-medium">Run details</summary><dl class="grid min-w-0 gap-x-6 gap-y-3 border-b pb-4 text-body-sm sm:grid-cols-2"><div><dt class="text-muted-foreground">Workflow</dt><dd><a class="break-all underline" href={`${base}/workflows/definitions/${encodeURIComponent(run.workflow_slug ?? run.workflow_id)}?version=${run.workflow_version}`}>{run.document?.title ?? run.workflow_slug ?? "Workflow"} · Version {run.workflow_version}</a></dd></div><div><dt class="text-muted-foreground">Coordinator</dt><dd class="break-all">{run.coordinator ? memberName(run.coordinator.address_id) : "Awaiting an agent"}{#if run.coordinator && run.status !== "completed"}<span class="block text-caption text-muted-foreground">Lease until <Timestamp value={run.coordinator.lease_until} /></span>{/if}</dd></div><div><dt class="text-muted-foreground">Started / finished</dt><dd><Timestamp value={run.started_at} fallback="Not started" /> / <Timestamp value={run.completed_at ?? run.finished_at} fallback="Not finished" /></dd></div><div><dt class="text-muted-foreground">Duration</dt><dd>{duration}</dd></div></dl></details>
    <p role="status" class="text-body-sm text-muted-foreground">{copied ? `${copied} copied.` : ""}</p>{#if copyError}<p role="alert" class="text-body-sm text-destructive">{copyError}</p>{/if}
    {#if !run.enabled}<p class="rounded-md border bg-muted p-3 text-body-sm">New workflow work is disabled. This existing run can still record results, recover coordination and complete evaluation.</p>{/if}
    {#if run.preparation}<WorkflowPreparation {run} allowed={canRun && !$report.isError} />{/if}
    <Section id="result" title="Result">{#if run.summary}<WorkflowMarkdown text={run.summary} />{:else}<p class="text-body text-muted-foreground">{run.status === "pending" ? "Prepared; no agent has started execution." : "No result summary has been recorded yet."}</p>{/if}</Section>
    {#if issues.length || run.status !== "completed"}<Section id="open-work" title="Open work"><div class="space-y-3 border-l-2 border-warning pl-3 text-body">
      {#if run.status === "pending"}<p>Give the assignment below to an existing agent to continue preparation or start after confirmation. Preparation does not launch a session.</p>{/if}
      {#if run.status === "evaluating"}<p class="font-semibold">Evaluation pending</p><p>Work has ended. The coordinator must assess the evidence and either improve the workflow or explain why no change is needed before this run can complete.</p>{/if}
      {#if run.cancel_requested}<p>Cancellation requested. Existing external work must be checked before its outcome can be recorded.</p>{/if}
      {#if run.coordinator && estimatedServerNow !== null && Date.parse(run.coordinator.lease_until) < estimatedServerNow && run.status !== "completed"}<p>Coordinator lease expired. Recover coordination without restarting tasks automatically.</p>{/if}
      {#if issues.length}<ul class="list-disc pl-5 space-y-2">{#each issues as issue}<li class="break-words"><WorkflowValue value={issue} /></li>{/each}</ul>{/if}
      {#if taskRows.some(t => t.status === "uncertain")}<p>Uncertain attempts require reconciliation of the old process and target system before another attempt can start.</p>{/if}
    </div></Section>{/if}
    {#if run.criteria?.length}
        {#snippet criterionList(criteria: NonNullable<typeof run.criteria>)}
          <ul class="space-y-3">{#each criteria as criterion}<li class="min-w-0"><div class="flex flex-wrap gap-2"><WorkflowStatus value={criterion.status} /><span class="text-body font-medium">{run.document?.goal.success_criteria.find(c => c.id === criterion.id)?.text ?? criterion.id}</span></div><p class="mt-1 max-w-[65ch] break-words text-body">{criterion.reason}</p>{#if criterion.evidence_ids?.length}<p class="break-words text-caption text-muted-foreground">Evidence: {criterion.evidence_ids.join(", ")}</p>{/if}</li>{/each}</ul>
        {/snippet}
      <Section id="acceptance" title="Acceptance checks" description={`${run.criteria.filter(c => c.status === "met").length} of ${run.criteria.length} recorded checks met.`}>

        {@render criterionList(run.criteria.filter(c => c.status !== "met"))}
        {#if run.criteria.some(c => c.status === "met")}<details class="mt-3"><summary class="cursor-pointer py-2 text-body font-medium">Passed checks ({run.criteria.filter(c => c.status === "met").length})</summary><div class="mt-3">{@render criterionList(run.criteria.filter(c => c.status === "met"))}</div></details>{/if}
      </Section>
    {/if}
    {#if Object.keys(facts).length}<Section id="handover" title="Handover"><WorkflowFacts values={facts} groupTitle="handover" /></Section>{/if}
    {#if run.status !== "completed"}<Section title={run.status === "pending" ? "Agent assignment" : "Continuation assignment"}><pre class="max-w-full whitespace-pre-wrap break-words rounded-md border bg-muted p-3 text-body-sm [overflow-wrap:anywhere]">{assignment}</pre><Button class="mt-2" variant="outline" onclick={() => copy(assignment, "Assignment")}>Copy assignment</Button></Section>{/if}
    {#if run.status === "pending" && !run.preparation && preparationDefinition}<details class="border-b pb-3"><summary class="cursor-pointer text-body font-semibold">Edit prepared run inputs</summary><div class="mt-3 max-w-3xl"><WorkflowRunForm definition={preparationDefinition} {run} allowed={canRun} /></div></details>{:else if Object.keys(run.inputs).length}<details><summary class="cursor-pointer py-1 text-body-sm">Run inputs</summary><WorkflowFacts values={run.inputs} label="Run inputs" /></details>{/if}
    <Section id="tasks" title="Tasks" description={`${taskRows.filter(t => t.status === "succeeded").length} of ${run.document?.tasks.length ?? taskRows.length} succeeded. Task success and run completion are separate.`}>
      <details open={run.status !== "completed" || taskRows.some(t => !["succeeded", "skipped"].includes(t.status)) || !!$taskPages.hasNextPage}><summary class="cursor-pointer py-2 text-body font-medium">Task evidence ({run.document?.tasks.length ?? taskRows.length})</summary><div class="mt-3"><ol class="divide-y">{#each taskRows as task (task.task_id)}{@const instruction = run.document?.tasks.find(t => t.id === task.task_id)}<li class="min-w-0 py-4 first:pt-0"><details open={openTasks.includes(task.task_id)} ontoggle={e => { if (e.currentTarget.open) openTasks = [...new Set([...openTasks,task.task_id])]; else openTasks = openTasks.filter(id => id !== task.task_id); }}><summary class="cursor-pointer"><span class="inline-flex max-w-full flex-wrap items-center gap-2 align-middle"><span class="break-words text-body font-semibold">{task.title}</span><WorkflowStatus value={task.status} />{#if run.document?.knowledge.some(k => k.required_check && instruction?.knowledge_ids.includes(k.id))}<span class="text-body-sm text-muted-foreground">Source receipt required before claim</span>{/if}</span></summary><div class="mt-2 space-y-3 pl-4">{#if task.reason}<p class="text-body-sm">{task.reason}</p>{/if}{#if task.skip_reason}<p class="text-body-sm">Skip reason: {statusLabel(task.skip_reason)}</p>{/if}<p class="break-words text-body-sm">{task.claim ? `Claimed by ${memberName(task.claim.owner_address_id)} · Host ${run.members.find(m => m.address_id === task.claim!.owner_address_id)?.host_id ?? "not recorded"}` : "No active claim"}{#if task.claim}<span class="block text-caption text-muted-foreground">Generation {task.claim.generation} · {task.claim.recovery ? "Reconciliation" : "Execution"} lease until <Timestamp value={task.claim.lease_until} /></span>{/if}</p>{#if instruction}<p class="text-body-sm text-muted-foreground">{instruction.depends_on.length ? `Depends on ${instruction.depends_on.map(id => taskRows.find(t => t.task_id === id)?.title ?? id).join(", ")}` : "No dependencies; can run independently."}</p><WorkflowMarkdown text={instruction.instructions} />{/if}{#if openTasks.includes(task.task_id)}<WorkflowTaskDetail runId={run.run_id} taskId={task.task_id} />{/if}</div></details></li>{/each}</ol>
      {#if $taskPages.hasNextPage}<Button variant="outline" disabled={$taskPages.isFetchingNextPage} onclick={() => $taskPages.fetchNextPage()}>More tasks</Button>{/if}</div></details>{#if $taskPages.isError}<StateBlock state="error" message="Could not load all tasks; retained task data may be stale." onRetry={() => $taskPages.refetch()} />{/if}
    </Section>
    <Section title="Collaboration"><details open={run.status !== "completed"}><summary class="cursor-pointer py-2 text-body font-medium">Participants ({run.members.length})</summary><p class="mt-2 text-body-sm text-muted-foreground">Membership does not mean an agent is online or its work has finished.</p><ul class="divide-y">{#each run.members as member (member.address_id)}<li class="flex min-w-0 flex-wrap items-start justify-between gap-2 py-3"><div class="min-w-0"><p class="break-all text-body font-medium">{memberName(member.address_id)}</p><p class="text-body-sm text-muted-foreground">{member.engine ?? "Engine not recorded"} · {member.fqdn ?? `Host ${member.host_id ?? "not recorded"}`}</p><p class="text-caption text-muted-foreground">Session binding {member.binding_generation ?? "not recorded"} · Reachability not measured here</p></div><WorkflowStatus value={member.status} /></li>{/each}</ul>{#if !run.members.length}<p class="text-body-sm text-muted-foreground">No participants yet.</p>{/if}
      {#if run.invitations.length}<details class="mt-3"><summary class="cursor-pointer py-1 text-body font-medium">Invitations ({run.invitations.length})</summary><ul class="divide-y">{#each run.invitations as invitation}<li class="py-3"><div class="flex flex-wrap items-center gap-2"><span class="break-all text-body">{invitation.name ?? invitation.target_address_id}</span><WorkflowStatus value={invitation.status} /></div><p class="text-body-sm">{invitation.reason}</p>{#if invitation.expires_at}<p class="text-caption text-muted-foreground">Expires <Timestamp value={invitation.expires_at} /></p>{/if}</li>{/each}</ul></details>{/if}
      </details>{#if run.communication}{#if canChat}<Button class="mt-3" variant="outline" href={`${base}/agents?view=live&room=${encodeURIComponent(run.communication.room_id)}`}>{run.status === "completed" ? "Read group history" : "Open run group"}</Button>{:else}<p class="mt-3 text-body-sm">Group content requires agent_messaging.reveal_content in addition to workflow access.</p>{/if}{:else}<p class="mt-3 text-body-sm text-muted-foreground">A shared group is created when a second participant accepts.</p>{/if}
    </Section>
    <Section id="evaluation" title="Evaluation">
      {#if evaluation}<div class="space-y-3"><WorkflowStatus value={run.evaluation?.status} /><h3 class="text-body font-semibold">{evaluation.decision === "no_change" ? (run.evaluation?.status === "final" ? "No changes needed" : "Proposed no change") : evaluation.decision === "revise" ? (run.evaluation?.status === "final" ? "Workflow improved" : "Proposed workflow improvement") : "Evaluation draft"}</h3>{#if typeof evaluation.reason === "string"}<WorkflowMarkdown text={evaluation.reason} />{/if}{#if Array.isArray(evaluation.findings) && evaluation.findings.length}<details><summary class="cursor-pointer py-2 text-body font-medium">Findings ({evaluation.findings.length})</summary><ul class="list-disc pl-5 space-y-2">{#each evaluation.findings as finding}<li class="break-words text-body-sm"><WorkflowValue value={typeof finding === "object" && finding && "text" in finding ? finding.text : finding} /></li>{/each}</ul></details>{/if}{#if Array.isArray(evaluation.lessons) && evaluation.lessons.length}<details><summary class="cursor-pointer py-2 text-body font-medium">Lessons for future runs ({evaluation.lessons.length})</summary><ul class="list-disc pl-5">{#each evaluation.lessons as lesson}<li class="break-words text-body-sm"><WorkflowValue value={lesson} /></li>{/each}</ul></details>{/if}{#if run.evaluation?.applied_version}<a class="text-body underline" href={`${base}/workflows/definitions/${encodeURIComponent(run.workflow_slug ?? run.workflow_id)}?version=${run.evaluation.applied_version}`}>Published version {run.evaluation.applied_version}</a>{/if}{#if run.evaluation?.diff || $appliedVersion.data?.diff}<details ontoggle={e => showDiff = e.currentTarget.open}><summary class="cursor-pointer py-2 text-body font-medium">Workflow changes</summary>{#if showDiff}<div class="mt-3"><WorkflowVersionDiff diff={run.evaluation?.diff ?? $appliedVersion.data?.diff} /></div>{/if}</details>{/if}{#if $appliedVersion.isError}<StateBlock state="error" message="Could not load the published improvement diff." onRetry={() => $appliedVersion.refetch()} />{/if}</div>{:else}<p class="text-body-sm text-muted-foreground">{run.status === "evaluating" ? "Required evaluation has not been saved yet." : "Evaluation follows the end of execution."}</p>{/if}
    </Section>
    <Section id="history" title="History"><details><summary class="cursor-pointer py-2 text-body font-medium">Run events</summary><ol class="divide-y">{#each $events.data?.pages.flatMap(p => p.items) ?? [] as event (event.id)}<li class="py-3"><div class="flex flex-wrap items-baseline justify-between gap-2"><p class="text-body font-medium">{statusLabel(event.type.replaceAll(".", " "))}</p><span class="text-caption text-muted-foreground"><Timestamp value={event.created_at} /></span></div><p class="mt-1 break-words text-body-sm text-muted-foreground">{actorName(event.actor)}</p><details class="mt-1 text-body-sm"><summary class="cursor-pointer py-1">Event details</summary><pre class="whitespace-pre-wrap break-words text-caption [overflow-wrap:anywhere]">{displayValue(event.actor)}
{displayValue(event.detail)}</pre></details></li>{/each}</ol>{#if !$events.isPending && !$events.isError && !$events.data?.pages[0]?.items.length}<p class="text-body-sm text-muted-foreground">No events recorded.</p>{/if}{#if $events.hasNextPage}<Button variant="outline" disabled={$events.isFetchingNextPage} onclick={() => $events.fetchNextPage()}>More events</Button>{/if}</details>{#if $events.isError}<StateBlock state="error" message="Could not load run history. Retained events may be stale." onRetry={() => $events.refetch()} />{/if}</Section>
    <WorkflowRunControls {run} allowed={canRun && !$report.isError} />
    <details class="text-body-sm"><summary class="cursor-pointer py-1">Report identity</summary><p class="break-all">Run {run.run_id}</p>{#if safeWorkflowUrl(run.report_url)}<a class="break-all underline" href={safeWorkflowUrl(run.report_url)!}>{run.report_url}</a>{/if}</details>
  {/if}
</PageShell>
